      "path": "pyproject.toml",
      "content": "[tool.poetry]\nname = \"agentdebugx\"\nversion = \"0.5.2\"\ndescription = \"Portable error analysis, tracing, and recovery framework for agentic AI systems. Import as `agentdebug`.\"\nauthors = [\"ULab @ UIUC <ulab@illinois.edu>\"]\nlicense = \"MIT\"\nreadme = \"README.md\"\nhomepage = \"https://www.agentdebugx.com\"\nrepository = \"https://github.com/AgentDebugX/AgentDebugX\"\ndocumentation = \"https://github.com/AgentDebugX/AgentDebugX\"\nkeywords = [\n    \"llm\",\n    \"agents\",\n    \"debugging\",\n    \"observability\",\n    \"failure-analysis\",\n    \"agent-debugging\",\n    \"agentic-ai\",\n    \"tracing\",\n    \"evaluation\",\n]\nclassifiers = [\n    \"Development Status :: 4 - Beta\",\n    \"Intended Audience :: Developers\",\n    \"Intended Audience :: Science/Research\",\n    \"License :: OSI Approved :: MIT License\",\n    \"Operating System :: OS Independent\",\n    \"Programming Language :: Python :: 3\",\n    \"Programming Language :: Python :: 3.9\",\n    \"Programming Language :: Python :: 3.10\",\n    \"Programming Language :: Python :: 3.11\",\n    \"Programming Language :: Python :: 3.12\",\n    \"Programming Language :: Python :: 3.13\",\n    \"Topic :: Scientific/Engineering :: Artificial Intelligence\",\n    \"Topic :: Software Development :: Debuggers\",\n    \"Topic :: Software Development :: Quality Assurance\",\n    \"Topic :: System :: Monitoring\",\n    \"Typing :: Typed\",\n]\npackages = [\n    { include = \"agentdebug\", from = \"src\" }\n]\ninclude = [\n    \"LICENSE\",\n    \"README.md\",\n    \"docs/**/*\",\n    \"src/agentdebug/py.typed\",\n    \"src/agentdebug/**/README.md\",\n    \"src/agentdebug/rerun/RUNNER_SPEC.md\",\n    \"src/agentdebug/rerun/SIMULATION_SPEC.md\",\n    \"src/agentdebug/rerun/ACTOR_TASK_SPEC.md\",\n    \"src/agentdebug/integrations/agentdebug_skill/**/*.md\",\n    \"src/agentdebug/diagnose/detect/rules/packs/*/manifest.json\",\n    \"src/agentdebug/diagnose/component_manifests/**/*.json\",\n    \"src/agentdebug/gui/config/*.json\",\n]\n\n[tool.poetry.dependencies]\npython = \">=3.9, <4.0\"\n# Pydantic v1 and v2 both supported via runtime shims in agentdebug.models.\npydantic = \">=1.10,<3.0\"\n# httpx powers the OpenAI-compatible LLM client.\nhttpx = \">=0.24,<1.0\"\n\n# GUI / computer-use (OSWorld / CUA) integration — optional.\n# Every entry MUST stay optional so a core install pulls none of them.\n#\n# The whole GUI stack lives in `agentdebug.gui`, split by how much it costs to\n# install: the RCA main path needs only `pillow` (lazily, for screenshot\n# decoding), `agentdebug.gui.memory` needs `gui-memory`, and the provider\n# adapters, batch pipeline and Streamlit app need `gui-app`.\n# `tests/test_gui_boundary.py` fails the build if any of them leak into an\n# `import agentdebug.gui`.\npillow = { version = \"*\", optional = true }\n\nanthropic = { version = \"*\", optional = true }\nchromadb = { version = \"*\", optional = true }\nlangchain-core = { version = \"*\", optional = true }\nlangchain-chroma = { version = \"*\", optional = true }\nlangchain-openai = { version = \"*\", optional = true }\nopenai = { version = \"*\", optional = true }\npandas = { version = \"*\", optional = true }\nscikit-learn = { version = \"*\", optional = true }\nstreamlit = { version = \"*\", optional = true }\nstreamlit-adjustable-columns = { version = \"*\", optional = true }\ntogether = { version = \"*\", optional = true }\n\n# Optional integrations — install via `pip install agentdebugx[langgraph]` etc.\ncrewai = { version = \"*\", optional = true }\nopenai-agents = { version = \"*\", optional = true }\nopentelemetry-api = { version = \"*\", optional = true }\nopentelemetry-sdk = { version = \"*\", optional = true }\nfastapi = { version = \"*\", optional = true }\nuvicorn = { version = \"*\", optional = true }\nhuggingface_hub = { version = \"*\", optional = true }\n\n[tool.poetry.extras]\nlanggraph = [\"langchain-core\"]\n# GUI RCA over OSWorld/CUA trajectories. `agentdebug.gui` itself needs nothing\n# beyond the core install; pillow adds screenshot decoding.\ngui = [\"pillow\"]\n# Lesson / episodic memory: agentdebug.gui.memory and .tools.lesson_explorer.\n# `scikit-learn` also sharpens `.evolving.alignment`, which otherwise falls back\n# to a Counter heuristic and runs fine on a core install.\ngui-memory = [\n    \"chromadb\",\n    \"langchain-core\",\n    \"langchain-chroma\",\n    \"langchain-openai\",\n    \"scikit-learn\",\n]\n# Provider adapters, the batch pipeline (`python -m agentdebug.gui`) and the\n# Streamlit annotation app (`agentdebug.gui.vis`).\ngui-app = [\n    \"anthropic\",\n    \"openai\",\n    \"pandas\",\n    \"pillow\",\n    \"streamlit\",\n    \"streamlit-adjustable-columns\",\n    \"together\",\n]\ncrewai = [\"crewai\"]\nopenai-agents = [\"openai-agents\"]\notel = [\"opentelemetry-api\", \"opentelemetry-sdk\"]\nui = [\"fastapi\", \"uvicorn\"]\nhub-hf = [\"huggingface_hub\"]\nall = [\n    \"anthropic\",\n    \"chromadb\",\n    \"langchain-core\",\n    \"langchain-chroma\",\n    \"langchain-openai\",\n    \"openai\",\n    \"pandas\",\n    \"pillow\",\n    \"scikit-learn\",\n    \"streamlit\",\n    \"streamlit-adjustable-columns\",\n    \"together\",\n    \"crewai\",\n    \"openai-agents\",\n    \"opentelemetry-api\",\n    \"opentelemetry-sdk\",\n    \"fastapi\",\n    \"uvicorn\",\n    \"huggingface_hub\",\n]\n\n[tool.poetry.scripts]\nagentdebug = \"agentdebug.cli:main\"\n\n[tool.poetry.group.dev.dependencies]\npre-commit = \"^3.6.0\"\nnbmake = \"^1.5.0\"\ntypes-setuptools = \"^69.0.0.0\"\nruff = \"^0.3.0\"\ncommitizen = \"^3.14.1\"\nmypy = \"^1.8.0\"\nbeartype = \"^0.17.1\"\n# Optional deps re-listed here so `poetry install` picks them up for dev.\nlangchain-core = \"*\"\nopentelemetry-api = \"*\"\nopentelemetry-sdk = \"*\"\nfastapi = \"*\"\nuvicorn = \"*\"\n\n[tool.poetry.group.test.dependencies]\npytest = \"^8.0.0\"\npytest-asyncio = \"^0.23.5\"\npytest-cov = \"^7.1.0\"\npytest-mock = \"^3.15.1\"\nhypothesis = \"^6.98.0\"\n\n[build-system]\nrequires = [\"poetry-core>=1.9.0\"]\nbuild-backend = \"poetry.core.masonry.api\"\n\n[tool.mypy]\nignore_missing_imports = true\ncheck_untyped_defs = true\nfollow_imports = \"skip\"\nexplicit_package_bases = true\nmypy_path = \"src\"\nstrict = true\nplugins = [\"pydantic.mypy\"]\nwarn_redundant_casts = true\nwarn_unused_ignores = true\nwarn_return_any = true\nstrict_optional = true\ndisallow_untyped_defs = true\ndisallow_incomplete_defs = true\n\n[tool.pytest.ini_options]\ntestpaths = [\"tests\"]\npython_files = \"test_*.py\"\naddopts = \"-v\"\nmarkers = [\n    \"slow: marks tests as slow\",\n    \"integration: marks tests as integration tests\",\n]\n\n[tool.coverage.run]\nsource = [\"agentdebug\"]\nomit = [\"tests/*\", \"**/__init__.py\"]\n\n[tool.coverage.report]\nexclude_lines = [\n    \"pragma: no cover\",\n    \"def __repr__\",\n    \"if __name__ == .__main__.:\",\n    \"raise NotImplementedError\",\n    \"raise ImportError\",\n    \"except ImportError:\",\n]\n\n[tool.codespell]\nignore-words-list = \"dout, te, indicies, astroid\"\nskip = [\"data\", \".git\", \"*.pyc\", \"*.csv\", \"*.json\"]\nquiet-level = 3\n\n[tool.ruff]\nline-length = 88\ntarget-version = \"py39\"\n\n[tool.ruff.lint]\nselect = [\n    \"E\",  # pycodestyle errors\n    \"W\",  # pycodestyle warnings\n    \"F\",  # pyflakes\n    \"C\",  # flake8-comprehensions\n    \"B\",  # flake8-bugbear\n]\nignore = [\"E203\", \"E266\", \"E501\", \"C901\"]\n\n[tool.ruff.format]\nquote-style = \"single\"\nindent-style = \"space\"\nskip-magic-trailing-comma = false\nline-ending = \"auto\"\n\n[tool.ruff.lint.mccabe]\nmax-complexity = 10\n\n[tool.ruff.lint.per-file-ignores]\n\"__init__.py\" = [\"F401\"]\n\"tests/*\" = [\"S101\"]\n\n[tool.commitizen]\nname = \"cz_conventional_commits\"\nversion = \"0.1.0\"\ntag_format = \"v$version\"\nbump_message = \"bump: version $current_version → $new_version\"\nversion_files = [\n    \"pyproject.toml:version\",\n    \"src/agentdeb